export type CellType = "code" | "markdown";

/** A cell as exchanged with the LLM (and exported to .ipynb). */
export interface NotebookCell {
  cell_type: CellType;
  source: string;
}

/** One prompt → notebook round-trip, used as context for the next prompt. */
export interface HistoryTurn {
  prompt: string;
  cells: NotebookCell[];
}

/** A submitted prompt, shown in the notebook as an executed input cell. */
export interface PromptCell {
  id: string;
  kind: "prompt";
  source: string;
  execCount: number;
  turn: number;
}

/** A code/markdown cell generated by the model for a given turn. */
export interface GeneratedCell {
  id: string;
  kind: CellType;
  source: string;
  turn: number;
}

export type UICell = PromptCell | GeneratedCell;
